func (q *Queries) SetFindingLinearIssue(ctx context.Context, arg SetFindingLinearIssueParams) error {
	_, err := q.db.Exec(ctx, setFindingLinearIssue, arg.ID, arg.LinearIssueID)
	return err
}

const setPremiseAnswer = `-- name: SetPremiseAnswer :one
UPDATE findings SET premise_answer = $1, updated_at = now()
WHERE id = $2 AND premise IS NOT NULL AND premise_answer IS NULL
RETURNING id
`

type SetPremiseAnswerParams struct {
	Answer pgtype.Text `json:"answer"`
	ID     int64       `json:"id"`
}

// Resposta humana à pergunta de um achado com premissa de produto (label aplicada no Linear).
func (q *Queries) SetPremiseAnswer(ctx context.Context, arg SetPremiseAnswerParams) (int64, error) {
	row := q.db.QueryRow(ctx, setPremiseAnswer, arg.Answer, arg.ID)
	var id int64
	err := row.Scan(&id)
	return id, err
}

const suppressionsByFinding = `-- name: SuppressionsByFinding :many
SELECT id, repo, module, category, fingerprint, pattern, reason, finding_id, expires_at, created_at FROM suppressions WHERE finding_id = $1 ORDER BY id
`

func (q *Queries) SuppressionsByFinding(ctx context.Context, findingID pgtype.Int8) ([]Suppression, error) {
	rows, err := q.db.Query(ctx, suppressionsByFinding, findingID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Suppression{}
	for rows.Next() {
		var i Suppression
		if err := rows.Scan(
			&i.ID,
			&i.Repo,
			&i.Module,
			&i.Category,
			&i.Fingerprint,
			&i.Pattern,
			&i.Reason,
			&i.FindingID,
			&i.ExpiresAt,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const trackedIssues = `-- name: TrackedIssues :many
SELECT li.linear_id, li.identifier, li.state_type, li.finding_id, f.state AS finding_state
FROM linear_issues li JOIN findings f ON f.id = li.finding_id
WHERE li.role = 'primary' AND f.merged_into IS NULL
  AND (f.state IN ('open', 'executing') OR li.state_type NOT IN ('completed', 'canceled', 'duplicate'))
ORDER BY li.id
`

type TrackedIssuesRow struct {
	LinearID     string `json:"linear_id"`
	Identifier   string `json:"identifier"`
	StateType    string `json:"state_type"`
	FindingID    int64  `json:"finding_id"`
	FindingState string `json:"finding_state"`
}

// Issues principais que o polling sincroniza: as de achado que ainda espera decisão humana e as
// que ainda não chegaram a um estado final no Linear. A segunda parte cobre o achado resolvido
// pelo merge do PR (fixed) cuja issue só depois vai para Done: sem ela, o estado da issue no
// banco ficava parado (visto na EX-12).
func (q *Queries) TrackedIssues(ctx context.Context) ([]TrackedIssuesRow, error) {
	rows, err := q.db.Query(ctx, trackedIssues)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TrackedIssuesRow{}
	for rows.Next() {
		var i TrackedIssuesRow
		if err := rows.Scan(
			&i.LinearID,
			&i.Identifier,
			&i.StateType,
			&i.FindingID,
			&i.FindingState,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateLinearIssueState = `-- name: UpdateLinearIssueState :exec
UPDATE linear_issues SET state_name = $2, state_type = $3, synced_at = now() WHERE linear_id = $1
`

type UpdateLinearIssueStateParams struct {
	LinearID  string `json:"linear_id"`
	StateName string `json:"state_name"`
	StateType string `json:"state_type"`
}

func (q *Queries) UpdateLinearIssueState(ctx context.Context, arg UpdateLinearIssueStateParams) error {
	_, err := q.db.Exec(ctx, updateLinearIssueState, arg.LinearID, arg.StateName, arg.StateType)
	return err
}

const webhookEventProcessed = `-- name: WebhookEventProcessed :one
SELECT EXISTS (SELECT 1 FROM webhook_events WHERE provider = $1 AND event_id = $2 AND processed_at IS NOT NULL)::bool
`

type WebhookEventProcessedParams struct {
	Provider string `json:"provider"`
	EventID  string `json:"event_id"`
}

// O evento já foi aplicado? Um evento gravado sem processed_at (o Linear falhou no meio) volta a
// ser aplicado no poll ou na reentrega seguinte.
func (q *Queries) WebhookEventProcessed(ctx context.Context, arg WebhookEventProcessedParams) (bool, error) {
	row := q.db.QueryRow(ctx, webhookEventProcessed, arg.Provider, arg.EventID)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}
